<script setup>import { Head,Link,router,useForm } from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({course:Object,enrollments:Object,students:Array,search:String}); const form=useForm({student_ids:[],starts_at:'',ends_at:''}); let query=props.search||''; const search=()=>router.get(`/admin/courses/${props.course.id}/enrollments`,{search:query},{preserveState:true}); const toggle=(e)=>router.put(`/admin/courses/${props.course.id}/enrollments/${e.id}`,{status:e.status==='ACTIVE'?'INACTIVE':'ACTIVE',starts_at:e.starts_at,ends_at:e.ends_at});</script>
<template><AppLayout><Head title="ثبت‌نام هنرجویان"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><h1 class="text-xl font-bold">هنرجویان دوره «{{ course.title }}»</h1><form class="mt-5 grid gap-3 md:grid-cols-2" @submit.prevent="form.post(`/admin/courses/${course.id}/enrollments`)"><div class="md:col-span-2"><div class="flex gap-2"><input v-model="query" placeholder="جست‌وجوی هنرجو"><button type="button" @click="search" class="rounded-xl border px-4">جست‌وجو</button></div><div class="mt-2 max-h-48 overflow-y-auto rounded-xl border p-2"><label v-for="student in students" class="flex gap-2 p-2"><input v-model="form.student_ids" type="checkbox" :value="student.id" class="h-4 w-4">{{ student.first_name }} {{ student.last_name }} — {{ student.mobile }}</label></div><p class="text-sm text-red-600">{{ form.errors.student_ids||form.errors['student_ids.0'] }}</p></div><div><label>شروع اختیاری</label><input v-model="form.starts_at" type="datetime-local"></div><div><label>پایان اختیاری</label><input v-model="form.ends_at" type="datetime-local"></div><button class="rounded-xl bg-teal-700 px-4 py-2 text-white">ثبت‌نام</button></form></section><section class="rounded-2xl border bg-white p-5"><div class="overflow-x-auto"><table class="w-full text-right text-sm"><thead><tr class="border-b"><th class="p-3">هنرجو</th><th>وضعیت</th><th>بازه دسترسی</th><th></th></tr></thead><tbody><tr v-for="e in enrollments.data" class="border-b"><td class="p-3">{{ e.student.first_name }} {{ e.student.last_name }}</td><td>{{ e.status==='ACTIVE'?'فعال':'غیرفعال' }}</td><td>{{ e.starts_at||'—' }} تا {{ e.ends_at||'—' }}</td><td><button @click="toggle(e)" class="text-teal-700">{{ e.status==='ACTIVE'?'غیرفعال‌سازی':'فعال‌سازی' }}</button></td></tr></tbody></table></div></section><Link :href="`/admin/courses/${course.id}`" class="inline-block text-teal-700">بازگشت به دوره</Link></div></AppLayout></template>
